mapper.update:
update 
set delivery_claim_token=#{token}::uuid,delivery_claim_until=#{until},
    attempt=least(attempt+1,#{maxAttempts})
where tenant_id=#{row.tenantId} and id=#{row.id} and terminal_event_key=#{row.eventKey}
  and delivery_status in ('PENDING','EXHAUSTED') and next_retry_at <= #{now}
  and (delivery_claim_until is null or delivery_claim_until <= #{now})
